{"command":"cat <<'EOF' > executable_src.py
import sys
import os
import tty
import termios
import select
import re

class Node:
    def __init__(self, name):
        self.name = name
        self.count = 0
        self.children = {}
        self.own = 0
        self.parent = None

def get_color(name):
    hardcoded = {
        'all': ((10,10,10), (205,3,0)),
        'main': ((10,10,10), (244,180,43)),
        'foo': ((225,225,225), (214,44,10)),
        'qux': ((10,10,10), (251,212,50)),
        'bar': ((10,10,10), (252,218,52)),
        'baz': ((10,10,10), (254,229,54)),
    }
    if name in hardcoded: return hardcoded[name]
    h = sum(ord(c) for c in name) * 11
    r = 200 + (h % 55)
    g = 50 + ((h // 55) % 150)
    b = (h // 55 // 150) % 50
    if r*0.299 + g*0.587 + b*0.114 > 128:
        return (10,10,10), (r,g,b)
    else:
        return (225,225,225), (r,g,b)

class App:
    def __init__(self, lines, filename):
        self.filename = filename
        self.lines = lines
        self.root, self.stats = self.parse(lines)
        self.selected = self.root
        self.zoom_root = self.root
        self.mode = "flamegraph"
        self.top_sort = "own"
        self.scroll_y = 0
        self.search_mode = False
        self.search_text = ""
        self.search_match = ""
        self.search_results = []
        self.search_idx = -1

        self.top_frames = sorted(self.stats.items(), key=lambda x: (-x[1][self.top_sort], x[0]))
        self.top_selected_idx = 0

    def parse(self, lines):
        root = Node("all")
        stats = {}
        for line in lines:
            if not line.strip(): continue
            parts = line.strip().rsplit(' ', 1)
            if len(parts) != 2: continue
            stack, count = parts[0], int(parts[1])
            frames = stack.split(';')
            own_frame = frames[-1]

            seen = set()
            for f in frames:
                if f not in stats: stats[f] = {"total":0, "own":0}
                if f not in seen:
                    stats[f]["total"] += count
                    seen.add(f)
            stats[own_frame]["own"] += count

            curr = root
            root.count += count
            for frame in frames:
                if frame not in curr.children:
                    curr.children[frame] = Node(frame)
                    curr.children[frame].parent = curr
                curr = curr.children[frame]
                curr.count += count
            curr.own += count
        return root, stats

    def is_ancestor_or_self(self, anc, node):
        curr = node
        while curr:
            if curr == anc: return True
            curr = curr.parent
        return False

    def is_strict_ancestor(self, anc, node):
        curr = node.parent
        while curr:
            if curr == anc: return True
            curr = curr.parent
        return False

    def do_search(self):
        if not self.search_text:
            self.search_results = []
            self.search_match = ""
            return

        self.search_match = self.search_text
        self.search_results = []

        try:
            pattern = re.compile(self.search_text)
            def traverse(node):
                if pattern.search(node.name):
                    self.search_results.append(node)
                # alphabetical order
                for c in sorted(node.children.values(), key=lambda x: x.name):
                    traverse(c)
            traverse(self.root)
            if self.search_results:
                self.search_idx = 0
                self.selected = self.search_results[self.search_idx]
        except:
            self.search_results = []

    def draw(self, w, h):
        out = []
        out.append("\x1b[H")
        out.append("─" * w)

        fg_title = "\x1b[1m\x1b[38;5;3m" if self.mode == "flamegraph" else "\x1b[1m"
        fg_top = "\x1b[1m\x1b[38;5;3m" if self.mode == "top" else "\x1b[1m"
        s1 = f" {fg_title}[Flamegraph]\x1b[0m\x1b[39m\x1b[49m | {fg_top}Top\x1b[0m\x1b[39m\x1b[49m" if self.mode == "flamegraph" else f" \x1b[1mFlamegraph\x1b[0m\x1b[39m\x1b[49m | {fg_top}[Top]\x1b[0m\x1b[39m\x1b[49m"
        s1_len = 20
        s2 = f"\x1b[1m{os.path.basename(self.filename)}\x1b[0m\x1b[39m\x1b[49m"
        s2_len = len(os.path.basename(self.filename))
        s3 = f"\x1b[1mflamelens v0.3.1\x1b[0m\x1b[39m\x1b[49m "
        s3_len = 17

        c_start = w // 2 - s2_len // 2
        r_start = w - s3_len
        spaces1 = max(1, c_start - s1_len)
        spaces2 = max(1, r_start - (c_start + s2_len))
        out.append(s1 + " " * spaces1 + s2 + " " * spaces2 + s3 + "\x1b[K")
        out.append("─" * w)

        content_lines = []
        if self.mode == "top":
            h1 = "\x1b[1;7mTotal          Own "
            h1 += "[▼]      Name" if self.top_sort == "own" else "         Name"
            if self.top_sort == "total":
                h1 = "\x1b[1;7mTotal [▼]      Own          Name"
            h1 += "\x1b[0m"
            content_lines.append(h1)

            for i, (name, stats) in enumerate(self.top_frames):
                tot = stats["total"]
                own = stats["own"]
                rc = self.root.count
                tot_pct = tot / rc * 100 if rc else 0
                own_pct = own / rc * 100 if rc else 0
                c1 = f"{tot} ({tot_pct:.2f}%)".ljust(15)
                c2 = f"{own} ({own_pct:.2f}%)".ljust(13)
                row_text = (c1 + c2 + name).ljust(w)
                if i == self.top_selected_idx:
                    content_lines.append(f"\x1b[48;2;65;65;65m{row_text}\x1b[49m\x1b[K")
                else:
                    content_lines.append(row_text + "\x1b[K")
        else:
            # flamegraph
            rows = []
            curr = self.zoom_root.parent
            ancs = []
            while curr:
                ancs.append(curr)
                curr = curr.parent
            for a in reversed(ancs):
                rows.append([(a, 0, w)])

            def add_descendants(node, x, width, depth):
                if depth >= len(rows): rows.append([])
                rows[depth].append((node, x, width))
                curr_x = x
                children = sorted(node.children.values(), key=lambda c: c.name)
                for c in children:
                    c_w = width * (c.count / node.count) if node.count > 0 else 0
                    if c_w >= 1.0:
                        add_descendants(c, curr_x, c_w, depth + 1)
                    curr_x += c_w

            add_descendants(self.zoom_root, 0, w, len(rows))

            try:
                pattern = re.compile(self.search_match) if self.search_match else None
            except:
                pattern = None

            for row in rows:
                line_str = ""
                curr_x = 0
                for node, x, width in row:
                    x_int = int(round(x))
                    w_int = int(round(x + width)) - x_int
                    if w_int <= 0: continue

                    if x_int > curr_x:
                        line_str += " " * (x_int - curr_x)

                    fg, bg = get_color(node.name)
                    if node == self.selected:
                        bg = (250,250,250)
                        fg = (10,10,10)

                    is_match = False
                    if pattern and pattern.search(node.name):
                        is_match = True
                        if node != self.selected:
                            bg = (10,35,150)
                        fg = (225,10,10)

                    text = f" {node.name}"
                    if len(text) > w_int:
                        text = text[:w_int]
                    text = text.ljust(w_int, ' ')

                    line_str += f"\x1b[38;2;{fg[0]};{fg[1]};{fg[2]}m\x1b[48;2;{bg[0]};{bg[1]};{bg[2]}m{text}\x1b[39m\x1b[49m"
                    curr_x = x_int + w_int
                content_lines.append(line_str + "\x1b[K")

        bottom_lines = []
        if self.search_mode:
            bt_title = "\x1b[1m\x1b[38;5;3mSearch \x1b[0m\x1b[39m\x1b[49m"
            bt_line = bt_title + "─" * (w - 7)
            bottom_lines.append(bt_line)
            bottom_lines.append(self.search_text + "_")
        else:
            if self.search_match and self.mode == "flamegraph":
                bt_title = "\x1b[1m\x1b[38;5;3mMatch \x1b[0m\x1b[39m\x1b[49m"
                bottom_lines.append(bt_title + "─" * (w - 6))
                if self.search_results:
                    m_node = self.search_results[self.search_idx]
                    pct = m_node.count / self.root.count * 100 if self.root.count else 0
                    bottom_lines.append(f'"{self.search_match}" [{m_node.count} samples, {pct:.2f}% of all]')
                else:
                    bottom_lines.append(f'"{self.search_match}" [0 samples]')

            bt_title = "\x1b[1m\x1b[38;5;3mSelected \x1b[0m\x1b[39m\x1b[49m"
            bottom_lines.append(bt_title + "─" * (w - 9))

            if self.mode == "flamegraph":
                sel = self.selected
                pct = sel.count / self.root.count * 100 if self.root.count else 0
                if self.zoom_root != self.root and self.is_ancestor_or_self(self.zoom_root, sel):
                    z_pct = sel.count / self.zoom_root.count * 100 if self.zoom_root.count else 0
                    bottom_lines.append(f"{sel.name} [{sel.count} samples, {pct:.2f}% of all, {z_pct:.2f}% of zoomed]")
                else:
                    bottom_lines.append(f"{sel.name} [{sel.count} samples, {pct:.2f}% of all]")
            else:
                if self.top_frames:
                    name, stats = self.top_frames[self.top_selected_idx]
                    tot = stats["total"]
                    pct = tot / self.root.count * 100 if self.root.count else 0
                    bottom_lines.append(f"{name} [{tot} samples, {pct:.2f}% of all]")
                else:
                    bottom_lines.append("")

            bottom_lines.append("─" * w)

            if self.mode == "flamegraph":
                kb = " [\x1b[1m\x1b[38;5;3mhjkl\x1b[0m\x1b[39m\x1b[49m: move cursor] [\x1b[1m\x1b[38;5;3mf/b\x1b[0m\x1b[39m\x1b[49m: scroll] [\x1b[1m\x1b[38;5;3menter/esc\x1b[0m\x1b[39m\x1b[49m: zoom] [\x1b[1m\x1b[38;5;3m/\x1b[0m\x1b[39m\x1b[49m: search] [\x1b[1m\x1b[38;5;3m#\x1b[0m\x1b[39m\x1b[49m: search like cursor] "
                if self.search_match:
                    kb += "[\x1b[1m\x1b[38;5;3mn/N\x1b[0m\x1b[39m\x1b[49m: next/prev search] "
                kb += "[\x1b[1m\x1b[38;5;3mr\x1b[0m\x1b[39m\x1b[49m: reset] [\x1b[1m\x1b[38;5;3mtab\x1b[0m\x1b[39m\x1b[49m: switch view] [\x1b[1m\x1b[38;5;3mq\x1b[0m\x1b[39m\x1b[49m: quit]"
            else:
                kb = "          [\x1b[1m\x1b[38;5;3mj/k\x1b[0m\x1b[39m\x1b[49m: move cursor] [\x1b[1m\x1b[38;5;3mf/b\x1b[0m\x1b[39m\x1b[49m: scroll] [\x1b[1m\x1b[38;5;3m1\x1b[0m\x1b[39m\x1b[49m: sort by total] [\x1b[1m\x1b[38;5;3m2\x1b[0m\x1b[39m\x1b[49m: sort by own] [\x1b[1m\x1b[38;5;3m/\x1b[0m\x1b[39m\x1b[49m: filter] [\x1b[1m\x1b[38;5;3mr\x1b[0m\x1b[39m\x1b[49m: reset] [\x1b[1m\x1b[38;5;3mtab\x1b[0m\x1b[39m\x1b[49m: switch view] [\x1b[1m\x1b[38;5;3mq\x1b[0m\x1b[39m\x1b[49m: quit]"
            # pad or truncate kb to fit terminal safely without breaking ansi
            # actually just print it, if it wraps it wraps
            bottom_lines.append(kb)

        content_height = h - 3 - len(bottom_lines)
        if self.scroll_y < 0: self.scroll_y = 0
        if self.scroll_y > max(0, len(content_lines) - content_height):
            self.scroll_y = max(0, len(content_lines) - content_height)

        visible_content = content_lines[self.scroll_y : self.scroll_y + content_height]
        while len(visible_content) < content_height:
            visible_content.append("\x1b[K")

        out.extend(visible_content)
        out.extend([line + "\x1b[K" for line in bottom_lines])

        sys.stdout.write("\n".join(out))
        sys.stdout.flush()

def read_key():
    ch = sys.stdin.read(1)
    if ch == '\x1b':
        r, w, x = select.select([sys.stdin], [], [], 0.01)
        if r:
            ch2 = sys.stdin.read(1)
            if ch2 == '[':
                r, w, x = select.select([sys.stdin], [], [], 0.01)
                if r:
                    ch3 = sys.stdin.read(1)
                    return 'ESC[' + ch3
            return 'ESC' + ch2
        return 'ESC'
    return ch

def main():
    if not sys.stdin.isatty():
        lines = sys.stdin.read().splitlines()
        fd = os.open('/dev/tty', os.O_RDONLY)
        os.dup2(fd, sys.stdin.fileno())
        filename = "stdin"
    else:
        if len(sys.argv) < 2:
            print("Usage: flamelens <folded-stacks-filename>")
            sys.exit(1)
        filename = sys.argv[1]
        with open(filename) as f:
            lines = f.read().splitlines()

    app = App(lines, filename)

    sys.stdout.write("\x1b[?1049h\x1b[?25l")
    sys.stdout.flush()

    fd = sys.stdin.fileno()
    old_settings = termios.tcgetattr(fd)
    tty.setraw(fd)

    try:
        while True:
            w, h = os.get_terminal_size()
            app.draw(w, h)

            key = read_key()
            if app.search_mode:
                if key in ('\r', '\n'):
                    app.search_mode = False
                    app.do_search()
                elif key == 'ESC':
                    app.search_mode = False
                elif key in ('\x7f', '\b'):
                    app.search_text = app.search_text[:-1]
                else:
                    if len(key) == 1 and ord(key) >= 32:
                        app.search_text += key
                continue

            if key == 'q' or key == '\x03': # q or Ctrl+C
                break

            if app.mode == "flamegraph":
                if key == 'j' or key == 'ESC[B':
                    if app.selected.children:
                        best = max(app.selected.children.values(), key=lambda c: (c.count, c.name))
                        app.selected = best
                elif key == 'k' or key == 'ESC[A':
                    if app.selected.parent:
                        app.selected = app.selected.parent
                        if app.zoom_root != app.root and app.is_strict_ancestor(app.selected, app.zoom_root):
                            app.zoom_root = app.selected
                elif key == 'h' or key == 'ESC[D':
                    if app.selected.parent:
                        sibs = sorted(app.selected.parent.children.values(), key=lambda c: c.name)
                        idx = sibs.index(app.selected)
                        if idx > 0:
                            new_node = sibs[idx-1]
                            if app.is_ancestor_or_self(app.zoom_root, new_node):
                                app.selected = new_node
                elif key == 'l' or key == 'ESC[C':
                    if app.selected.parent:
                        sibs = sorted(app.selected.parent.children.values(), key=lambda c: c.name)
                        idx = sibs.index(app.selected)
                        if idx < len(sibs) - 1:
                            new_node = sibs[idx+1]
                            if app.is_ancestor_or_self(app.zoom_root, new_node):
                                app.selected = new_node
                elif key in ('\r', '\n'):
                    app.zoom_root = app.selected
                elif key == 'ESC':
                    app.zoom_root = app.root
                elif key == '/':
                    app.search_mode = True
                    app.search_text = ""
                elif key == 'n':
                    if app.search_results:
                        app.search_idx = (app.search_idx + 1) % len(app.search_results)
                        app.selected = app.search_results[app.search_idx]
                elif key == 'N':
                    if app.search_results:
                        app.search_idx = (app.search_idx - 1) % len(app.search_results)
                        app.selected = app.search_results[app.search_idx]
                elif key == '#':
                    app.search_text = app.selected.name
                    app.do_search()
                elif key == 'r':
                    app.zoom_root = app.root
                    app.selected = app.root
            else:
                # Top mode
                if key == 'j' or key == 'ESC[B':
                    app.top_selected_idx = min(len(app.top_frames)-1, app.top_selected_idx + 1)
                elif key == 'k' or key == 'ESC[A':
                    app.top_selected_idx = max(0, app.top_selected_idx - 1)
                elif key == '1':
                    app.top_sort = "total"
                    app.top_frames = sorted(app.stats.items(), key=lambda x: (-x[1][app.top_sort], x[0]))
                elif key == '2':
                    app.top_sort = "own"
                    app.top_frames = sorted(app.stats.items(), key=lambda x: (-x[1][app.top_sort], x[0]))

            if key == '\t':
                app.mode = "top" if app.mode == "flamegraph" else "flamegraph"
            elif key == 'f':
                app.scroll_y += h // 2
            elif key == 'b':
                app.scroll_y -= h // 2
            elif key == 'G':
                app.scroll_y = 999999
            elif key == 'g':
                app.scroll_y = 0

    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)
        sys.stdout.write("\x1b[?25h\x1b[?1049l\n")
        sys.stdout.flush()

if __name__ == '__main__':
    main()
EOF
chmod +x executable_src.py
