                    app.top_frames = sorted(app.stats.items(), key=lambda x: (-x[1][app.top_sort], x[0]))
                elif key == '2':
                    app.top_sort = "own"
                    app.top_frames = sorted(app.stats.items(), key=lambda x: (-x[1][app.top_sort], x[0]))
                elif key == 'r':
                    pass

            if key == '\t':
                app.mode = "top" if app.mode == "flamegraph" else "flamegraph"
            elif key == 'f':
                app.scroll_y += h // 2
            elif key == 'b':
                app.scroll_y -= h // 2
            elif key == 'G':
                app.scroll_y = 999999
            elif key == 'g':
