import sys
import os
import tty
import termios
import select
import re

class Node:
    def __init__(self, name):
        self.name = name
        self.count = 0
        self.children = {}
        self.own = 0
        self.parent = None

def get_color(name):
    hardcoded = {
        'all': ((10,10,10), (250,250,250)),  # actually wait, I decided 'all' normally is (205,3,0).
        'main': ((10,10,10), (244,180,43)),
        'foo': ((225,225,225), (214,44,10)),
        'qux': ((10,10,10), (251,212,50)),
        'bar': ((10,10,10), (252,218,52)),
        'baz': ((10,10,10), (254,229,54)),
    }
    if name in hardcoded: return hardcoded[name]
    if name == 'all': return ((225,225,225), (205,3,0)) # default for all

    h = sum(ord(c) for c in name) * 11
    r = 200 + (h % 55)
    g = 50 + ((h // 55) % 150)
    b = (h // 55 // 150) % 50
    if r*0.299 + g*0.587 + b*0.114 > 128:
        return (10,10,10), (r,g,b)
    else:
        return (225,225,225), (r,g,b)

